// ── Helper Functions for AI Context ──────────────────────────────────────────

/**
 * Get formatted diagnosis context for the AI analyzer prompt.
 * Returns a concise summary of the diagnosis dataset.
 */
export function getDiagnosisContext(): string {
  const byCrop: Record<string, DiagnosisEntry[]> = {};
  for (const d of DIAGNOSIS_DATASET) {
    if (!byCrop[d.crop]) byCrop[d.crop] = [];
    byCrop[d.crop].push(d);
  }

  const lines: string[] = [];
  for (const [crop, entries] of Object.entries(byCrop)) {
    lines.push(`\n=== ${crop.toUpperCase()} DIAGNOSIS DATABASE ===`);
    for (const e of entries) {
      lines.push(
        `- ${e.diagnosisCategory}: ${e.diagnosisLabel} | ` +
        `Variety: ${e.variety}, Stage: ${e.growthStage}, ` +
        `Leaf: ${e.leafColor}/${e.discoloration}, ` +
        `Spots: ${e.spotPresence}${e.spotShape !== 'none' ? ` (${e.spotShape})` : ''}`
      );
    }
  }
  return lines.join('\n');
}

/**
 * Get formatted crop cultivation context for the AI analyzer prompt.
 * Returns key cultivation info for common crops.
 */
export function getCropContext(): string {
  // Pick top 10 most relevant crops with good data
  const keyCrops = ['ধান', 'পাট', 'আলু', 'টমেটো', 'বেগুন', 'সরিষা', 'কলা', 'আম', 'গম', 'ভুট্টা', 'পেঁয়াজ', 'রসুন', 'মরিচ'];
  const relevant = CROP_DATASET.filter(c => keyCrops.includes(c.nameBn));

  const lines: string[] = [];
  for (const crop of relevant) {
    const varieties = crop.varieties.slice(0, 3); // Only include top 3
    lines.push(`\n=== ${crop.nameBn} (${crop.nameEn}) ===`);
    for (const v of varieties) {
      const parts: string[] = [];
      if (v.season) parts.push(`মৌসুম: ${v.season}`);
      if (v.plantingTime) parts.push(`বপন: ${v.plantingTime.substring(0, 80)}`);
      if (v.harvestTime) parts.push(`ফসল: ${v.harvestTime.substring(0, 80)}`);
      if (v.fertilizer) parts.push(`সার: ${v.fertilizer.substring(0, 100)}`);
      if (v.tempRange) parts.push(`তাপ: ${v.tempRange}`);
      if (v.soilType) parts.push(`মাটি: ${v.soilType}`);
      lines.push(`  [${v.variety || 'সাধারণ'}] ${parts.join(' | ')}`);
    }
  }
  return lines.join('\n');
}
